const base=$('Build Safe ArcGIS Queries').item.json;
const source=base.source;
const features=Array.isArray($json.features)?$json.features:[];
const pick=(a,keys)=>{for(const k of keys){if(a[k]!==undefined&&a[k]!==null&&String(a[k]).trim()!=='')return a[k];}return null;};
const records=features.map((f,i)=>{
 const a=f.attributes||f;
 return {
  source_url:source.url,source_name:source.name||null,source_type:source.type||'arcgis',
  source_record_id:String(pick(a,[base.object_id_field,'PARNO','parno','NPARNO','nparno','PARCEL_ID','parcel_id','PIN','pin','OBJECTID','objectid'])||('feature-'+base.result_offset+i)),
  owner_name:pick(a,['OWNNAME','ownname','OWNER','owner','OWNER_NAME','owner_name']),
  property_address:pick(a,['SITUSADDR','situsaddr','SITEADDR','siteaddr','SITEADD','siteadd','ADDRESS','address','SITE_ADDRESS','site_address']),
  mailing_address:pick(a,['MAILADD','mailadd','MAILADDR','mailaddr','MAILING_ADDRESS','mailing_address']),
  county:pick(a,['COUNTY','county','COUNTY_NAME','county_name','CNTYNAME','cntyname'])||base.county||null,
  city:pick(a,['SITUSCITY','situscity','SCITY','scity','CITY','city','CITY_NAME','city_name'])||base.city||null,
  state:pick(a,['SITUSSTATE','situsstate','SSTATE','sstate','STATE','state','STATE_CODE','state_code','STNAME','stname'])||base.state||null,
  zip:pick(a,['SZIP','szip','ZIP','zip','ZIPCODE','zipcode','ZIP_CODE']),
  parcel_id:pick(a,['PARNO','parno','NPARNO','nparno','PARCEL_ID','parcel_id','PIN','pin']),
  assessed_value:pick(a,['PARVAL','parval','ASSESSED','assessed','ASSESSED_VALUE','assessed_value']),
  land_value:pick(a,['LANDVAL','landval','LAND_VALUE','land_value']),
  building_value:pick(a,['IMPROVVAL','improvval','BUILDING_VALUE','building_value','IMPROVEMENT_VALUE','improvement_value']),
  acreage:pick(a,['ACREAGE','acreage','ACRES','acres','GISACRES','gisacres']),
  property_type:pick(a,['PROP_TYPE','prop_type','PROPERTY_TYPE','property_type','LANDUSE','landuse','PARUSECODE','parusecode','PARUSECD2','parusecd2']),
  structure_indicator:pick(a,['STRUCT','struct','STRUCTURE_INDICATOR','structure_indicator']),
  structure_count:pick(a,['STRUCTNO','structno','STRUCTURE_COUNT','structure_count']),
  year_built:pick(a,['YEAR_BUILT','year_built','STRUCTYEAR','structyear']),
  building_sqft:pick(a,['BUILDING_SQFT','building_sqft','BLDG_SQFT','bldg_sqft']),
  sale_date:pick(a,['SALEDATE','saledate','LAST_SALE_DATE','last_sale_date']),
  sale_price:pick(a,['SALEPRICE','saleprice','LAST_SALE_PRICE','last_sale_price']),
  legal_description:pick(a,['LEGDECFULL','legdecfull','LEGAL_DESCRIPTION','legal_description']),
  raw_attributes:a
 };
});
return [{json:{success:true,request_id:base.request_id,source_url:source.url,records,record_count:records.length,page_index:base.page_index,result_offset:base.result_offset,query_filters_applied:base.query_filters_applied,limitations:base.pagination_limit_reached?['Layer does not advertise pagination support; only the first query page was collected.']:[]}}];

const items=$input.all();
const text=v=>String(v??'').trim();
const norm=v=>text(v).toUpperCase().replace(/[^A-Z0-9]+/g,' ').trim();
const first=(o,keys)=>{for(const k of keys){if(o[k]!==undefined&&o[k]!==null&&text(o[k])!=='')return o[k];}return null;};
const truthy=v=>{const s=norm(v);return v!==null&&v!==undefined&&s!==''&&!['0','N','NO','FALSE','NONE','NULL'].includes(s);};
const num=v=>{const n=Number(String(v??'').replace(/[$,]/g,''));return Number.isFinite(n)?n:null;};
const addressKey=v=>norm(v).replace(/\b(ROAD|RD|STREET|ST|AVENUE|AVE|DRIVE|DR|LANE|LN|COURT|CT|CIRCLE|CIR|HIGHWAY|HWY|BOULEVARD|BLVD|PARKWAY|PKWY)\b/g,'').replace(/\s+/g,'');
const output=[];
for(const item of items){
  const r=item.json||{}; const a=r.raw_attributes||{}; const criteria=Array.isArray(r.criteria)?r.criteria:[];
  const signals={}; const evidence=[]; const missing=[];
  const structureCount=num(r.structure_count);
  const structureIndicator=norm(r.structure_indicator);
  const propertyType=norm(r.property_type);
  const hasExplicitNoStructure=structureCount===0 || ['N','NO','NONE','0','VACANT'].includes(structureIndicator);
  const hasVacantUse=/\bVACANT\b/.test(propertyType)||/\bVACANT LAND\b/.test(propertyType);
  const site=addressKey(r.property_address); const mail=addressKey(r.mailing_address);
  const debt=first(a,['OUTSTANDING_DEBT','OUTSTANDING_LOAN','MORTGAGE_BALANCE','DEBT_AMOUNT','LIEN_AMOUNT','DEBT']);
  const value=num(first(a,['PARVAL','parval','ASSESSED_VALUE','assessed_value','MARKET_VALUE','market_value']));
  const explicitDebt=num(debt);
  for(const criterion of criteria){
    if(criterion==='vacant'){
      if(hasExplicitNoStructure||hasVacantUse) signals.vacant={status:'supported',confidence:hasVacantUse?'high':'medium',evidence:[hasVacantUse?'explicit vacant land/use description':'explicit no-structure indicator']};
      else signals.vacant={status:'needs_evidence',confidence:0,evidence:[],missing_fields:['structure_indicator_or_count','explicit_property_use']};
    }
    else if(criterion==='vacant_land'){
      if(/\bVACANT LAND\b/.test(propertyType)||(/\bLAND\b/.test(propertyType)&&hasExplicitNoStructure)) signals.vacant_land={status:'supported',confidence:0.9,evidence:['explicit land/vacant-land property use','explicit no-structure indicator'].filter(Boolean)};
      else if(hasExplicitNoStructure&&num(r.acreage)!==null) signals.vacant_land={status:'candidate_signal',confidence:0.6,evidence:['explicit no-structure indicator','explicit acreage'],missing_fields:['explicit_land_use_or_zoning']};
      else signals.vacant_land={status:'needs_evidence',confidence:0,evidence:[],missing_fields:['explicit_land_use_or_zoning','structure_indicator_or_count']};
    }
    else if(criterion==='absentee'){
      if(site&&mail&&site!==mail) signals.absentee={status:'supported',confidence:0.9,evidence:['site address differs from mailing address']};
      else signals.absentee={status:'needs_evidence',confidence:0,evidence:[],missing_fields:['site_address','mailing_address']};
    }
    else if(criterion==='high_equity'){
      if(explicitDebt!==null&&value!==null&&value>explicitDebt) signals.high_equity={status:'supported',confidence:0.8,evidence:['explicit property value','explicit outstanding debt'],equity_proxy:value-explicitDebt};
      else signals.high_equity={status:'needs_evidence',confidence:0,evidence:[],missing_fields:['outstanding_debt'],note:'Property value alone does not establish equity.'};
    }
    else if(criterion==='probate'){
      const k=Object.keys(a).find(k=>/probate|estate|decedent|heir/i.test(k)&&truthy(a[k]));
      signals.probate=k?{status:'supported',confidence:0.85,evidence:['explicit probate/estate field: '+k]}:{status:'needs_source',confidence:0,evidence:[],missing_source_types:['probate_record','court_record']};
    }
    else if(criterion==='pre_foreclosure'){
      const k=Object.keys(a).find(k=>/foreclosure|lis.?pendens|default|auction/i.test(k)&&truthy(a[k]));
      signals.pre_foreclosure=k?{status:'supported',confidence:0.85,evidence:['explicit foreclosure/default field: '+k]}:{status:'needs_source',confidence:0,evidence:[],missing_source_types:['foreclosure_record','court_record']};
    }
    else if(criterion==='fixer_upper'){
      const k=Object.keys(a).find(k=>/condition|code.?enforcement|permit|violation|repair|unsafe/i.test(k)&&truthy(a[k]));
      signals.fixer_upper=k?{status:'supported',confidence:0.8,evidence:['explicit condition/permit/code signal: '+k]}:{status:'needs_source',confidence:0,evidence:[],missing_source_types:['permit_record','code_enforcement'],missing_fields:['condition_signal']};
    }
    else if(criterion==='tax_delinquent'){
      const k=Object.keys(a).find(k=>/delinq|past.?due|tax.?due|tax.?status/i.test(k)&&truthy(a[k]));
      const amt=num(first(a,['DELINQUENT_TAX','DELINQ_TAX','DELINQUENT_AMOUNT','TAX_DELINQUENT','DELINQ_AMT']));
      signals.tax_delinquent=(k||amt>0)?{status:'supported',confidence:0.9,evidence:[k?'explicit tax-delinquency field: '+k:'explicit delinquent tax amount'],delinquent_tax_amount:amt}:{status:'needs_source',confidence:0,evidence:[],missing_source_types:['tax_delinquency','tax_record']};
    }
    else if(criterion==='distressed'){
      const keys=Object.keys(a).filter(k=>/delinq|foreclosure|lis.?pendens|code.?enforcement|violation|unsafe|permit|distress|default/i.test(k)&&truthy(a[k]));
      signals.distressed=keys.length?{status:'supported',confidence:0.8,evidence:keys.slice(0,5).map(k=>'explicit distress field: '+k)}:{status:'needs_source',confidence:0,evidence:[],missing_source_types:['tax_delinquency','foreclosure_record','permit_record','code_enforcement']};
    }
    else signals[criterion]={status:'needs_evidence',confidence:0,evidence:[],missing_fields:['criterion_specific_source']};
  }
  for(const [criterion,s] of Object.entries(signals)){ if(Array.isArray(s.evidence)) for(const e of s.evidence) evidence.push({criterion,status:s.status,detail:e}); if(Array.isArray(s.missing_fields)) missing.push(...s.missing_fields.map(field=>({criterion,field}))); if(Array.isArray(s.missing_source_types)) missing.push(...s.missing_source_types.map(source_type=>({criterion,source_type}))); }
  const supported=Object.values(signals).filter(s=>s.status==='supported').length;
  output.push({json:{...r,criterion_signals:signals,criterion_evidence:evidence,criterion_missing_fields:missing,criterion_match_count:supported,criterion_signal_version:'v1'}});
}
return output;
